      pricingTitle: "أسعار تاكسي مكة إلى المدينة",
      pricingText1: "فهم سعر تاكسي مكة إلى المدينة مهم قبل الحجز. في حرامين تاكسي عمرة، نقدم أسعارًا واضحة وشفافة بدون رسوم خفية.",
