      faqTitle: "الأسئلة المتداولة",
      faq1Question: "هل يجب أن أترك إكرامية لسائق التاكسي في المملكة العربية السعودية؟",
      faq1Answer: "الإكرامية في المملكة العربية السعودية غير مطلوبة، لكنها لفتة طيبة إذا كانت الخدمة ممتازة. إكرامية 10-20 ريال سخية إذا ساعدك سائقك في الأمتعة أو قدم رعاية استثنائية في رحلتك. سائقو حرامين تاكسي عمرة مهذبون ومحترفون. الإكرامية بالكامل تقريرك، لكنهم يقدرون دائمًا عندما تشعر أن الخدمة كانت أكثر مما تتوقع.",
      faq2Question: "كم يكلف تاكسي من مطار المدينة إلى المسجد النبوي؟",
      faq2Answer: "يتراوح سعر تاكسي مطار المدينة إلى المسجد النبوي من 170 ريال لسيدان كامري/سوناتا إلى 600 ريال لحافلة 50 مقعدًا، حسب اختيارك للمركبة. المسافة ليست طويلة جدًا، لذا فهي رحلة سريعة وفعالة للحجاج. سعرنا الثابت يضمن تسعيرًا واضحًا وسائقين محترفين ودعمًا في حمل الأمتعة.",
      faq3Question: "كم تكلف سيارة خاصة من المدينة إلى مكة؟",
      faq3Answer: "سيارة خاصة من المدينة إلى مكة تتراوح من 380 ريال لسيدان إلى 1000 ريال لحافلة كبيرة، بناءً على حجم مجموعتك ومتطلبات الراحة. الرحلة تغطي حوالي 450 كيلومترًا وأسعارنا الثابتة تشمل سائقين ذوي خبرة ووقودًا ورسوم عبور. حجز تاكسي خاص مع حرامين تاكسي عمرة يضمن رحلة مريحة ومباشرة بين المدن المقدستين مع أوقات مغادرة مرنة.",
      faq4Question: "هل هناك طرق أخرى للسفر من مكة إلى المدينة؟",
      faq4Answer: "نعم، يمكنك السفر بين مكة والمدينة باستخدام عدة بدائل، بما في ذلك حافلات بين المدن أو النقل المشترك أو قطار الحرمين السريع. الحافلات والقطارات تقدم خيارات ميزانية محدودة لكنها تتبع جداول زمنية ثابتة وتتوقف عدة مرات. خدمات التاكسي الخاصة مثل خدمة تاكسي حرامين توفر راحة من باب إلى باب مع توقيتات مرنة ومسارات مباشرة. هذا يجعل التاكسي مثاليًا للعائلات والحجاج المسنين أو أولئك الذين لديهم جداول زمنية ضيقة خلال رحلة العمرة.",
