      makkahText2: "نلتقطك من أي فندق في مكة. سواء كنت تقيم بالقرب من المسجد الحرام أو في العزيزية، سنصلك بسرعة. هل تريد زيارة جبل النور أو التسوق في المولات؟ نأخذك هناك براحة. هل تحتاج إلى الوصول إلى الحرم في أوقات الصلاة؟ نضمن وصولك مع وقت لتوفير.",
