      madinahText2: "نتعامل مع حجوزات تاكسي الفندق المدينة لزيارات المسجد النبوي ومسجد قباء وجبل أحد. يقترح سائقونا أفضل أوقات الزيارة لتجنب الحشود. ينتظرون بصبر بينما تكمل زيارتك.",
      madinahText3: "زيارات مسائية لأسواق التمر أو الأسواق التقليدية؟ نأخذك للتسوق ونعيدك بأمان. يوصي سائقونا بمتاجر أصلية حيث يشتري السكان المحليون. أنت تتجنب فخاخ السياح التي تفرض أسعارًا مبالغًا فيها.",
