      jeddahAirportText1: "مسار تاكسي مطار جدة إلى فندق مكة هو تخصصنا. تستغرق هذه الرحلة البالغة 92 كيلومترًا 60-90 دقيقة حسب حركة المرور. قاد سائقونا هذا الطريق آلاف المرات. يعرفون بالضبط أي ممرات تتحرك بشكل أسرع في أي وقت.",
      jeddahAirportText2: "يلتقي بك سائقك عند وصولات مطار جدة. يتتبع رحلتك، لذا لا تحتاج إلى الاتصال لشرح التأخيرات. يحمل لافتة باسمك مطبوعة بوضوح. تكتشفه بسهولة بين الحشود. في غضون دقائق، تجلس في مركبة نظيفة متجهة إلى مكة.",
