      madinahAirportText2: "مطار المدينة أصغر من مطار جدة. يتنقل سائقونا فيه بسهولة. ينتظرون في المخرج الصحيح، مما يضمن لقاءات سريعة. تستغرق القيادة إلى فنادق وسط المدينة 15-25 دقيقة، حسب الموقع.",
      madinahAirportText3: "نقود عبر مزارع التمور الجميلة والتطويرات الحديثة. يشير سائقونا إلى المعالم، مما يساعدك على توجيه نفسك في المدينة. هذا الود الودي يجعل الزوار لأول مرة يشعرون بالترحيب والراحة.",
