      airportText3: "Sopir Anda membantu memuat dan membongkar bagasi. Dia membuka pintu untuk penumpang lansia dan membantu keluarga dengan anak-anak.",
      makkahTitle: "Layanan Taksi Transportasi Hotel Makkah",
      makkahText1: "Layanan taksi transportasi hotel Makkah beroperasi 24/7 di seluruh kota suci. Anda dapat memesan perjalanan kapan saja, siang atau malam. Sopir kami mengetahui sistem jalan yang kompleks di Makkah dengan sempurna. Mereka menavigasi melalui lalu lintas dengan efisien, bahkan selama musim Umrah puncak.",
      makkahText2: "Kami menjemput Anda dari hotel mana pun di Makkah. Baik Anda menginap dekat Masjid al-Haram atau di Aziziyah, kami akan menjangkau Anda dengan cepat. Apakah Anda ingin mengunjungi Jabal al-Nour atau berbelanja di mal? Kami membawa Anda ke sana dengan nyaman. Perlu mencapai Haram untuk waktu sholat? Kami memastikan Anda tiba dengan waktu cadangan.",
      makkahText3: "Layanan taksi hotel Makkah juga mencakup transfer antar hotel. Kami memindahkan bagasi dan keluarga Anda dengan lancar. Anda tidak perlu membawa tas berat melalui jalan yang sibuk sendiri.",
      madinahTitle: "Layanan Taksi Transportasi Hotel Madinah",
      madinahText1: "Layanan taksi transportasi hotel Madinah menawarkan layanan yang sama luar biasa di kota Nabi. Hotel-hotel Madinah tersebar di berbagai area. Sopir kami mengetahui semuanya secara akrab. Anda tidak perlu menjelaskan arah atau menunjukkan peta.",
      madinahText2: "Kami menangani pemesanan taksi hotel Madinah untuk kunjungan ke Masjid Nabawi, Masjid Quba, dan Gunung Uhud. Sopir kami menyarankan waktu kunjungan terbaik untuk menghindari kerumunan. Mereka menunggu dengan sabar saat Anda menyelesaikan Ziyarat Anda.",
      madinahText3: "Kunjungan malam ke pasar kurma atau pasar tradisional? Kami membawa Anda berbelanja dan mengembalikan Anda dengan aman. Sopir kami merekomendasikan toko otentik di mana penduduk lokal berbelanja. Anda menghindari jebakan turis yang mengenakan harga yang melambung.",
      jeddahTitle: "Layanan Taksi Transportasi Hotel Jeddah",
      jeddahText1: "Layanan taksi transportasi hotel Jeddah melayani jamaah dan pelancong bisnis. Jeddah berfungsi sebagai kota gerbang bagi sebagian besar pengunjung Umrah. Banyak orang menghabiskan malam di sini sebelum bepergian ke Makkah atau setelah menyelesaikan Umrah sebelum terbang pulang.",
      jeddahText2: "Kami memindahkan Anda antara hotel dan atraksi wisata. Jika Anda ingin melihat distrik Al-Balad bersejarah atau berjalan di sepanjang Corniche, kami akan membawa Anda dengan nyaman.",
      jeddahText3: "Hotel-hotel Jeddah berkisar dari anggaran hingga kemewahan bintang lima. Layanan kami mencakup semua kategori harga. Kami tidak menghakimi berdasarkan tempat Anda menginap. Setiap penumpang menerima rasa hormat dan layanan luar biasa yang sama terlepas dari status hotel.",
      routesTitle: "Rute Bandara Khusus",
      routesSubtitle: "Koneksi langsung, cepat, dan aman dari bandara utama ke akomodasi Anda.",
      jeddahAirportTitle: "Bandara Jeddah ke Hotel Makkah",
      jeddahAirportText1: "Rute taksi bandara Jeddah ke hotel Makkah adalah spesialisasi kami. Perjalanan 92 kilometer ini memakan waktu 60-90 menit tergantung lalu lintas. Sopir kami telah mengemudi di jalan ini ribuan kali. Mereka tahu persis jalur mana yang bergerak lebih cepat pada waktu tertentu.",
      jeddahAirportText2: "Sopir Anda bertemu Anda di kedatangan Bandara Jeddah. Dia melacak penerbangan Anda, jadi Anda tidak perlu menelepon untuk menjelaskan keterlambatan. Dia membawa tanda dengan nama Anda tercetak dengan jelas. Anda menemukannya dengan mudah di antara kerumunan. Dalam hitungan menit, Anda duduk di kendaraan bersih menuju Makkah.",
      jeddahAirportText3: "Kami berhenti di Miqat jika Anda perlu memasuki Ihram. Sopir Anda menunjukkan fasilitas dan menunggu dengan sabar. Dia memastikan Anda menyelesaikan ritual penting ini dengan benar. Untuk keluarga dengan anak kecil, kami mengizinkan istirahat ke kamar mandi tanpa biaya tambahan.",
      madinahAirportTitle: "Bandara Madinah ke Hotel Madinah",
      madinahAirportText1: "Taksi bandara Madinah ke hotel Madinah membawa Anda langsung dari Bandara Internasional Pangeran Mohammad bin Abdulaziz ke akomodasi Anda. Bandara terletak di luar kota, membutuhkan transportasi andal. Anda tidak bisa berjalan ke hotel dari sana.",
      madinahAirportText2: "Bandara Madinah lebih kecil dari Bandara Jeddah. Sopir kami menavigasinya dengan mudah. Mereka menunggu di keluar yang benar, memastikan pertemuan cepat. Perjalanan ke hotel pusat kota memakan waktu 15-25 menit, tergantung lokasi.",
      madinahAirportText3: "Kami mengemudi melewati perkebunan kurma yang indah dan pembangunan modern. Sopir kami menunjukkan landmark, membantu Anda mengorientasikan diri di kota. Pengantar ramah ini membuat pengunjung pertama kali merasa diterima dan nyaman.",
      whyTitle: "Mengapa Haramain Menawarkan Transfer Hotel Terbaik?",
      whySubtitle: "Transfer hotel terbaik menggabungkan keandalan, kenyamanan, dan harga yang adil. Kami telah menyempurnakan keseimbangan ini selama bertahun-tahun melayani jamaah dan turis.",
      whyFeature1Title: "Kendaraan Sempurna",
      whyFeature1Desc: "Kendaraan kami selalu bersih. Kami menjaga standar tinggi. Kursi nyaman. AC bekerja dengan sempurna. Anda tidak duduk di taksi tua yang bau atau dengan kursi rusak. Armada kami mencakup model terbaru yang dipertahankan dalam kondisi luar biasa.",
      whyFeature2Title: "Sopir Profesional",
      whyFeature2Desc: "Sopir kami berperilaku secara profesional. Mereka berpakaian rapi. Mereka menyapa Anda dengan hormat. Mereka mengikuti hukum lalu lintas dengan hati-hati dan tidak merokok di kendaraan atau memutar musik keras. Perjalanan Anda terasa bermartabat dan damai.",
      whyFeature3Title: "Harga Transparan",
      whyFeature3Desc: "Kutipan yang kami berikan adalah apa yang Anda bayar. Tidak ada biaya tersembunyi yang muncul di akhir. Tidak ada biaya tambahan untuk bagasi, jam larut, atau keterlambatan lalu lintas. Anda membayar satu harga adil yang mencakup semuanya.",
      fleetTitle: "Armada untuk Layanan Transfer Hotel",
      fleetSubtitle: "Kami mempertahankan armada yang beragam melayani berbagai ukuran dan anggaran grup. Semua kendaraan kami memiliki AC yang berfungsi, tempat duduk nyaman, dan interior bersih.",
      fleet1Title: "Sedan (Toyota Camry/Sonata)",
      fleet1Pax: "Hingga 4 Penumpang",
      fleet1Bag: "Bagasi Sedang",
      fleet1Desc: "Mengakomodasi 4 penumpang dengan bagasi sedang. Sempurna untuk pasangan atau keluarga kecil yang bepergian ringan.",
      fleet2Title: "Van Toyota Hiace",
      fleet2Pax: "6-8 Penumpang",
      fleet2Bag: "Ruang Bagasi Luas",
      fleet2Desc: "Ideal untuk keluarga dengan anak-anak atau grup yang bepergian bersama. Ruang ekstra membuat perjalanan panjang lebih nyaman.",
      fleet3Title: "Minibus Coaster",
      fleet3Pax: "12-14 Penumpang",
      fleet3Bag: "Kapasitas Bagasi Grup",
      fleet3Desc: "Ini bekerja dengan sempurna untuk grup keluarga besar atau teman yang bepergian bersama untuk Umrah. Semua orang tetap bersama.",
      fleetBookBtn: "Pesan Sekarang via WhatsApp",
      ctaEyebrow: "Kesimpulan",
      ctaTitle: "Perjalanan di Arab Saudi Harus Terasa Lancar dan Bermartabat",
      ctaText1: "Perjalanan suci Anda layak mendapatkan layanan transfer hotel terbaik di Arab Saudi yang menghormati waktu, kenyamanan, dan anggaran Anda. Baik Anda membutuhkan taksi bandara Jeddah ke hotel Makkah atau taksi hotel Madinah ke bandara Madinah, kami melayani Anda secara profesional setiap saat.",
      ctaText2: "Di Haramain Umrah Taxi, kami telah menyempurnakan layanan taksi transportasi hotel Makkah, Madinah, dan Jeddah selama bertahun-tahun layanan yang berdedikasi.",
      ctaText3: "Pesan transfer hotel Arab Saudi Anda bersama kami hari ini melalui WhatsApp atau situs web kami. Biarkan kami menangani transportasi saat Anda fokus pada doa, ibadah, dan menciptakan kenangan yang diberkati.",
      ctaWhatsAppBtn: "Pesan via WhatsApp Sekarang",
      ctaCallBtn: "Hubungi Kami Langsung",
