      heroText2: "Taksi umrah pribadi kami memberikan seluruh kendaraan untuk keluarga Anda, langsung ke tujuan Anda. Tidak ada detour. Tidak ada asing yang mendengar percakapan Anda, dan tidak ada perkelahian untuk ruang bagasi.",
