      makkahTitle: "Taksi Umrah Pribadi di Makkah",
      makkahText1: "Taksi umrah pribadi di Makkah menavigasi jalan-jalan kompleks kota suci secara eksklusif untuk Anda. Lalu lintas Makkah meningkat di sekitar waktu sholat. Hotel dekat Masjid al-Haram berkerumun dengan erat.",
      makkahText2: "Sopir taksi pribadi di Makkah kami mengetahui setiap lorong secara akrab. Mereka mengantar Anda di pintu masuk hotel yang tepat, bukan jalan terdekat yang mengharuskan Anda berjalan dengan bagasi. Presisi ini menghemat energi yang Anda butuhkan untuk ibadah dan Tawaf.",
      nearHaramTitle: "Taksi Pribadi Dekat Masjid Al Haram",
      nearHaramText1: "Taksi umrah pribadi dekat masjid al haram memberikan kenyamanan krusial selama menginap Anda. Anda sholat lima kali sehari di Haram. Banyak jamaah bangun untuk sholat Tahajjud juga.",
      nearHaramText2: "Taksi umrah pribadi dekat haram kami merespons dalam hitungan menit dari panggilan Anda. Tidak ada menunggu taksi bersama untuk mengisi penumpang. Tidak akan ada argumen tentang harga. Sopir khusus Anda mengetahui hotel dan preferensi rutin Anda dari perjalanan sebelumnya bersama.",
