      madinahCard2Text2: "Anda mengontrol kecepatan tur sepenuhnya. Perlu sholat di Masjid Quba dengan damai? Kami menunggu dengan sabar. Fleksibilitas ini membuat Ziarat benar-benar bermakna alih-alih hanya kotak centang wisata.",
      intercityTitle: "Perjalanan Pribadi Antar Kota",
      intercityText1: "Layanan mobil pribadi Madinah ke Makkah menangani perjalanan 435 kilometer secara eksklusif untuk grup Anda. Anda berhenti untuk sholat, makan, atau istirahat kapan saja dibutuhkan tanpa mengakomodasi jadwal penumpang lain.",
      intercityText2: "Perjalanan kembali mobil pribadi Makkah ke Madinah menawarkan fleksibilitas dan kenyamanan yang sama, terutama saat bepergian dengan anak-anak atau orang tua lansia.",
      vehicleTitle: "Pilihan Kendaraan untuk Taksi Pribadi",
      vehicleOption1Title: "Taksi Umrah Pribadi 2 Kursi",
