      airportCard1Desc: "Dapatkan transportasi langsung dan nyaman setelah penerbangan internasional yang melelahkan. Satu kendaraan untuk keluarga dan bagasi Anda, tanpa menunggu shuttle dan tanpa berbagi dengan orang asing.",
      airportCard2Title: "Mobil Pribadi dari Madinah ke Bandara Madinah",
      airportCard2Desc: "Keberangkatan mulus dengan waktu penjemputan berdasarkan jadwal penerbangan Anda. Sopir Anda membantu dengan bagasi dan memastikan semua orang mencapai bandara dengan waktu untuk check-in dan keamanan.",
      whyTitle: "Mengapa Memilih Layanan Taksi Pribadi?",
