      heroFaqBtn: "Lihat FAQ",
      basicsEyebrow: "Dasar-dasar",
      basicsTitle: "Apa itu Damm?",
      basicsText1: "Istilah Damm merujuk pada ekspektasi atau hukuman wajib selama periode Haji dan Umrah jika jamaah telah melanggar peraturan jamaah.",
      basicsText2: "Damm dapat diterjemahkan sebagai kompensasi penyembelihan dalam bahasa Inggris, dan biasanya merujuk pada penyembelihan hewan (hewan Damm) untuk menebus dosa yang dilakukan selama ritual.",
      meaningTitle: "Makna dan Definisi Damm",
      meaningText1: "Fikih Islam mendefinisikan Damm berarti penyembelihan kambing atau domba, atau berkontribusi pada penyembelihan hewan yang lebih besar seperti unta atau sapi sebagai penebus untuk pelanggaran tertentu. Penyembelihan harus dilakukan di dalam Makkah kemudian diberikan kepada orang miskin.",
      meaningText2: "Damm berfungsi untuk mengingatkan seseorang untuk mematuhi peraturan yang ditetapkan untuk Haji dan Umrah, menekankan kepatuhan dan kerendahan hati kepada Allah.",
