      quranArabic: "وَأَتِمُّوا۟ ٱلْحَجَّ وَٱلْعُمْرَةَ لِلَّهِ ۚ فَإِنْ أُحْصِرْتُمْ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ (البقرة: ١٩٦)",
      quranTranslation: "“Dan sempurnakanlah ibadah haji dan umrah karena Allah. Jika kamu terhalang, maka [sedekahkanlah] hewan sembelihan yang mudah didapat.” (Surah Al-Baqarah 2:196)",
      obligationEyebrow: "Kewajiban",
      obligationTitle: "Kapan Damm Wajib?",
      obligationText: "Damm menjadi wajib dalam situasi tertentu—kelalaian, pelanggaran Ihram, kesalahan ritual, atau kehilangan ritual penting.",
