      hadithIntro: "Nabi (SAW) bersabda:",
      hadithArabic: "مَن حج فلم يرفث ولم يفسق رجع كيوم ولدته أمه (صحيح البخاري: ١٥٢١)",
      hadithTranslation: "“Barangsiapa yang menunaikan haji dan tidak melakukan rafats dan fasik, maka ia akan kembali seperti pada hari ia dilahirkan oleh ibunya.” (Shahih al-Bukhari: 1521)",
