      heroCities2: "&",
      heroCities3: "Madinah",
      heroText1: "Selepas 12 jam penerbangan, keluarga anda yang letih layak mendapatkan lebih baik daripada menjejalkan ke dalam kenderaan yang penuh sesak, membuat lima pemberhentian sebelum mencapai hotel anda.",
      heroText2: "Teksi umrah peribadi kami memberikan seluruh kenderaan untuk keluarga anda, terus ke destinasi anda. Tiada detour. Tiada orang asing yang mendengar perbualan anda, dan tiada pergaduhan untuk ruang bagasi.",
      heroBookBtn: "Tempah di WhatsApp Sekarang",
