      familiesEyebrow: "Dibina untuk Keluarga",
      familiesTitle: "Teksi Umrah Peribadi untuk Keluarga",
      familiesText1: "Kami di Haramain Umrah Taxi menawarkan teksi umrah peribadi untuk keluarga yang memahami keperluan keluarga yang unik dengan sempurna. Ibu yang menyusuikan bayi memerlukan privasi. Ibu bapa warga emas memerlukan rehat kerap. Kanak-kanak menjadi gelisah dalam perjalanan panjang, memerlukan rehat untuk berjalan dan bermain.",
      familiesText2: "Teksi kongsi memaksa anda menekan keperluan semula jadi ini. Penumpang lain terganggu oleh bayi yang menangis. Pemandu menolak pemberhentian tambahan.",
      familiesText3: "Anda menderita secara senyap, cuba mengakomodasi orang asing alih-alih fokus pada keselesaan keluarga dan ibadah anda.",
