      familiesCard4Title: "Perpaduan Keluarga",
      familiesCard4Desc: "Kekal bersama dalam satu kenderaan alih-alih terpisah di antara orang asing.",
      makkahTitle: "Teksi Umrah Peribadi di Makkah",
      makkahText1: "Teksi umrah peribadi di Makkah menavigasi jalan-jalan kompleks bandar suci secara eksklusif untuk anda. Lalu lintas Makkah meningkat di sekitar waktu solat. Hotel berhampiran Masjid al-Haram berkerumun dengan erat.",
      makkahText2: "Pemandu teksi peribadi di Makkah kami mengetahui setiap lorong secara akrab. Mereka mengantar anda di pintu masuk hotel yang tepat, bukan jalan berhampiran yang memerlukan anda berjalan dengan bagasi. Ketepatan ini menjimatkan tenaga yang anda perlukan untuk ibadah dan Tawaf.",
      nearHaramTitle: "Teksi Peribadi Berhampiran Masjid Al Haram",
      nearHaramText1: "Teksi umrah peribadi berhampiran masjid al haram memberikan keselesaan kritikal semasa menginap anda. Anda solat lima kali sehari di Haram. Banyak jemaah bangun untuk solat Tahajjud juga.",
      nearHaramText2: "Teksi umrah peribadi berhampiran haram kami bertindak balas dalam minit dari panggilan anda. Tiada menunggu teksi kongsi untuk mengisi penumpang. Tidak akan ada hujah tentang harga. Pemandu khusus anda mengetahui hotel dan keutamaan rutin anda dari perjalanan sebelumnya bersama.",
      madinahEyebrow: "Perkhidmatan Madinah",
      madinahTitle: "Perkhidmatan Teksi Umrah Peribadi di Madinah",
      madinahSubtitle: "Perkhidmatan teksi umrah peribadi di Madinah melayani suasana tenang bandar Nabi. Namun anda masih memerlukan pengangkutan peribadi yang boleh dipercayai untuk ibadah yang selesa dan lawatan Ziarah.",
      madinahCard1Title: "Teksi Peribadi di Madinah",
      madinahCard1Text1: "Teksi peribadi di Madinah kami menghubungkan anda ke Masjid Nabawi dengan mudah beberapa kali sehari. Signifikansi emosi mengunjungi masjid Nabi memerlukan pengangkutan yang menghormati keadaan rohani anda.",
      madinahCard1Text2: "Pemandu kami memahami ini secara mendalam dan melayani anda mengikutnya.",
      madinahCard2Title: "Lawatan Ziarah Madinah dalam Teksi Peribadi",
      madinahCard2Text1: "Perkhidmatan teksi umrah peribadi di Madinah merangkumi Ziarat komprehensif ke Gunung Uhud, Masjid Quba, dan tapak diberkati lain. Lawatan peribadi membolehkan anda menghabiskan masa sebanyak yang anda inginkan di setiap lokasi.",
      madinahCard2Text2: "Anda mengawal kelajuan lawatan sepenuhnya. Perlu solat di Masjid Quba dengan damai? Kami menunggu dengan sabar. Fleksibiliti ini menjadikan Ziarat benar-benar bermakna alih-alih hanya kotak semak pelancong.",
      intercityTitle: "Perjalanan Peribadi Antara Bandar",
