      intercityText2: "Perjalanan pulang kereta peribadi Makkah ke Madinah menawarkan fleksibiliti dan keselesaan yang sama, terutama apabila melancong dengan kanak-kanak atau ibu bapa warga emas.",
      vehicleTitle: "Pilihan Kenderaan untuk Teksi Peribadi",
      vehicleOption1Title: "Teksi Umrah Peribadi 2 Tempat Duduk",
      vehicleOption1Desc: "Sedan kami sempurna untuk pasangan yang melancong tanpa kanak-kanak. Anda menikmati pengangkutan yang luas dan selesa dengan kadar ekonomi untuk kumpulan kecil.",
      vehicleOption2Title: "Teksi Umrah Peribadi 4 Tempat Duduk",
      vehicleOption2Desc: "Sedan mengakomodasi empat penumpang dengan bagasi munasabah. Keluarga tiga atau empat melancong bersama secara peribadi tanpa membayar kenderaan besar yang tidak perlu.",
      airportEyebrow: "Pemindahan Lapangan Terbang",
